
.hud {
  width: 100%;
  max-width: 760px;
  margin: 0 auto;
  border: 1px solid var(--c-border);
  border-radius: 12px;
  background: var(--c-surface);
  color: var(--c-text);
  font-family: var(--font-body);
  font-size: 12px;
  line-height: 1.4;
  overflow: hidden;
}

.tabs {
  display: flex;
  border-bottom: 1px solid var(--c-border);
  background: var(--c-surface-2);
}

.tab {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 6px;
  border: none;
  border-bottom: 2px solid transparent;
  background: none;
  color: var(--c-text-muted);
  font-family: inherit;
  font-size: 11px;
  letter-spacing: 0.06em;
  cursor: pointer;
  transition:
    color 0.2s,
    border-color 0.2s;

  &:hover {
    color: var(--c-text);
  }

  &.active {
    color: var(--c-holy);
    border-bottom-color: var(--c-danger);
  }

  i {
    font-size: 11px;
  }
}

.pane {
  padding: 11px 12px 13px;
  animation: rise 0.32s ease-out;
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(4px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .pane {
    animation: none;
  }
}
