
.field-head {
  margin-bottom: 9px;

  h3 {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.12em;
    color: var(--c-holy);
  }

  p {
    margin-top: 2px;
    font-size: 11px;
    color: var(--c-text-muted);
  }
}

.readouts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 8px;
}

.readout {
  padding: 8px 10px;
  border: 1px solid var(--c-border);
  border-radius: 8px;
  background: var(--c-surface-2);

  dt {
    font-size: 10px;
    letter-spacing: 0.06em;
    color: var(--c-text-muted);

    i {
      margin-right: 4px;
    }
  }

  dd {
    margin-top: 2px;
    font-size: 16px;

    small {
      margin-left: 1px;
      font-size: 9px;
      color: var(--c-text-muted);
    }
  }
}

.flow-note {
  margin-top: 8px;
  font-size: 10px;
  line-height: 1.5;
  color: var(--c-text-muted);
}

.log-title {
  margin: 11px 0 6px;
  font-size: 11px;
  letter-spacing: 0.1em;
  color: var(--c-text-muted);
  font-weight: 600;
}

.log {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 5px;

  li {
    display: flex;
    gap: 8px;
    padding: 6px 9px;
    border-left: 2px solid var(--c-taint);
    border-radius: 0 6px 6px 0;
    background: var(--c-surface-2);
  }
}

.turn {
  flex: none;
  font-size: 10px;
  color: var(--c-text-muted);
  padding-top: 1px;
}

.entry {
  display: flex;
  flex-direction: column;
  min-width: 0;

  b {
    font-size: 11px;
    color: var(--c-holy);
  }

  span {
    font-size: 11px;
    line-height: 1.45;
    color: var(--c-text-muted);
    overflow-wrap: anywhere;
  }
}

.metric {
  font-family: var(--font-metric);
  font-variant-numeric: tabular-nums;

  &.audience {
    color: var(--c-audience);
  }

  &.star {
    color: var(--c-star);
  }
}
