
.abyss-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--c-border);
  background: linear-gradient(120deg, #1b0a24, var(--c-surface-2) 60%);
}

.identity {
  display: flex;
  align-items: center;
  gap: 9px;
  flex: 1 1 190px;
}

.sigil {
  flex: none;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 50%, var(--c-danger) 0 18%, transparent 19%),
    conic-gradient(from 45deg, var(--c-taint), var(--c-danger), var(--c-taint));
  box-shadow: 0 0 10px rgba(176, 38, 255, 0.5);
}

.labels {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.kind {
  font-size: 10px;
  letter-spacing: 0.1em;
  color: var(--c-text-muted);
}

.stage {
  font-size: 15px;
  font-weight: 700;
  color: var(--c-danger);
}

.gauges {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  flex: 2 1 300px;
}

.gauge {
  display: grid;
  grid-template-columns: auto auto;
  align-items: baseline;
  column-gap: 6px;
  min-width: 108px;
  flex: 1 1 108px;

  dt {
    grid-column: 1 / -1;
    font-size: 10px;
    letter-spacing: 0.08em;
    color: var(--c-text-muted);
  }

  dd {
    font-size: 14px;

    small {
      margin-left: 1px;
      font-size: 9px;
      color: var(--c-text-muted);
    }
  }

  .sub {
    font-size: 10px;
    color: var(--c-text-muted);
    text-align: right;
  }

  &.is-counter {
    grid-template-columns: auto;
  }
}

.bar {
  grid-column: 1 / -1;
  display: block;
  height: 4px;
  margin: 3px 0 2px;
  border-radius: 999px;
  background: var(--c-surface-3);
  overflow: hidden;

  i {
    display: block;
    height: 100%;
    background: linear-gradient(90deg, var(--c-taint), var(--c-danger));
    transition: width 0.5s;
  }

  &.is-version i {
    background: linear-gradient(90deg, var(--c-holy-accent), var(--c-taint));
  }
}

.metric {
  font-family: var(--font-metric);
  font-variant-numeric: tabular-nums;

  &.ergo {
    color: var(--c-ergo);
  }
}
