
.powers-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 9px;

  h3 {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.12em;
    color: var(--c-holy);
  }

  p {
    font-size: 10px;
    color: var(--c-text-muted);
  }
}

.list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 8px;
  list-style: none;
}

.power {
  display: flex;
  gap: 9px;
  padding: 8px 10px;
  border: 1px solid var(--c-border);
  border-radius: 8px;
  background: var(--c-surface-2);

  > i {
    flex: none;
    margin-top: 2px;
    font-size: 13px;
    color: var(--c-taint);
  }
}

.body {
  min-width: 0;
  flex: 1;
}

.row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.name {
  font-size: 12px;
  font-weight: 700;
}

.pips {
  display: inline-flex;
  gap: 2px;

  b {
    width: 8px;
    height: 3px;
    border-radius: 1px;
    background: var(--c-surface-3);

    &.on {
      background: var(--c-danger);
    }
  }
}

.desc {
  margin-top: 3px;
  font-size: 11px;
  line-height: 1.4;
  color: var(--c-text-muted);
}

.rite {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px;
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px dashed var(--c-border);
  font-size: 11px;

  b {
    font-family: var(--font-metric);
    font-size: 14px;
    color: var(--c-danger);
  }

  .hint {
    color: var(--c-text-muted);
    font-size: 10px;
  }
}
