
.maiden {
  display: block;
  width: 100%;
  padding: 0;
  border: 1px solid var(--c-border);
  border-radius: 10px;
  background: var(--c-surface-2);
  color: var(--c-text);
  font-family: var(--font-body);
  text-align: left;
  cursor: pointer;
  perspective: 1200px;
  transition:
    border-color 0.3s,
    box-shadow 0.3s;

  &:hover,
  &:focus-visible {
    border-color: var(--c-taint);
    box-shadow: 0 0 0 1px var(--c-taint);
    outline: none;
  }

  &.is-fallen {
    border-color: var(--c-danger);
  }
}

/* 两面同占一个网格单元：容器高度取较高的一面，不脱离文档流。 */
.faces {
  display: grid;
  transform-style: preserve-3d;
  transition: transform 0.62s cubic-bezier(0.34, 1.16, 0.5, 1);
}

.maiden.is-flipped .faces {
  transform: rotateY(180deg);
}

.face {
  grid-area: 1 / 1;
  padding: 10px;
  backface-visibility: hidden;
  display: flex;
  flex-direction: column;
  gap: 7px;
  border-radius: 9px;
}

.face-holy {
  background: linear-gradient(160deg, var(--c-surface-2), #2c1a3f 70%);
}

.face-abyss {
  transform: rotateY(180deg);
  background: linear-gradient(160deg, #2a0a22, var(--c-surface) 72%);
}

.head {
  display: flex;
  align-items: center;
  gap: 7px;
}

.titles {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1;
}

.order {
  font-size: 10px;
  letter-spacing: 0.14em;
  color: var(--c-text-muted);
}

.form {
  font-size: 14px;
  font-weight: 700;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.stage {
  flex: none;
  padding: 2px 6px;
  border: 1px solid currentcolor;
  border-radius: 999px;
  font-size: 10px;
  letter-spacing: 0.06em;
  color: var(--c-holy-accent);

  &[data-stage='侵染'] {
    color: var(--c-taint);
  }

  &[data-stage='堕转'] {
    color: var(--c-danger);
  }

  &.is-abyss {
    color: var(--c-danger);
    background: rgba(255, 61, 110, 0.12);
  }
}

/* 星徽：圣辉态是完整菱形，魔娼态裂开一道。 */
.emblem {
  flex: none;
  width: 18px;
  height: 18px;
  background: linear-gradient(135deg, var(--c-holy), var(--c-holy-accent));
  clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%);

  &.is-cracked {
    background: linear-gradient(135deg, var(--c-danger), var(--c-taint));
    clip-path: polygon(50% 0%, 100% 50%, 50% 62%, 20% 100%, 0% 50%);
  }
}

.note {
  font-size: 11px;
  line-height: 1.45;
  color: var(--c-text-muted);
}

.stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}

.stat dt,
.details dt {
  font-size: 10px;
  letter-spacing: 0.06em;
  color: var(--c-text-muted);
}

.stat dd {
  font-size: 13px;
}

.metric {
  font-family: var(--font-metric);
  font-variant-numeric: tabular-nums;

  small {
    margin-left: 1px;
    font-size: 9px;
    color: var(--c-text-muted);
  }

  &.audience {
    color: var(--c-audience);
  }
}

.meter {
  height: 5px;
  border-radius: 999px;
  background: var(--c-surface-3);
  overflow: hidden;

  &.is-abyss .meter-fill {
    background: linear-gradient(90deg, var(--c-taint), var(--c-danger));
  }
}

.meter-fill {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--c-holy-accent), var(--c-taint));
  transition: width 0.5s;
}

.details {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px 8px;

  dd {
    font-size: 11px;
    overflow-wrap: anywhere;
  }

  .unknown {
    color: var(--c-text-muted);
    font-style: italic;
  }
}

@media (max-width: 420px) {
  .details,
  .stats {
    grid-template-columns: 1fr;
  }
}
